/** Each entry's links in the relations its fields read (EmDash 1.x keeps a
    relation editor's choice apart from the entry, so a list has none of
    them): one request per entry per field, a hundred links a page, six at a
    time, as the ids they link. A request that fails leaves that field empty
    on that entry and is said once (emdashNotes); after three, the rest are
    not asked. It never throws: the entries are still the entries. */
async function emdashRelations(items, relations, ask) {
  const jobs = [];
  for (const it of Array.isArray(items) ? items : []) {
    if (!emdashIsObj(it) || !it.id) continue;
    for (const [k, r] of Object.entries(emdashIsObj(relations) ? relations : {})) {
      if (emdashIsObj(r) && typeof r.relation === 'string' && r.relation) jobs.push([it, k, r]);
    }
  }
  let i = 0;
  let failures = 0;
  const mark = (it, slot, k, v) => { it[slot] = { ...(emdashIsObj(it[slot]) ? it[slot] : {}), [k]: v }; };
  const one = async ([it, k, r]) => {
    mark(it, '_relations', k, []);
    if (failures >= 3) { mark(it, '_relationFailed', k, 'not asked after three requests failed'); return; }
    const end = r.side === 'child' ? 'parents' : 'children';
    const ids = [];
    let cursor = '';
    try {
      for (let page = 0; page < 10; page++) {
        const answer = await ask('/content/' + encodeURIComponent(it.type ?? '') + '/' + encodeURIComponent(it.id) + '/references/'
          + encodeURIComponent(r.relation) + '/' + end + '?limit=100' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''));
        if (!emdashIsObj(answer) || answer.success === false || !emdashIsObj(answer.data) || !Array.isArray(answer.data[end])) {
          throw new Error(emdashIsObj(answer) && emdashIsObj(answer.error) && answer.error.message ? String(answer.error.message) : 'the answer holds no list of linked entries');
        }
        for (const x of answer.data[end]) if (emdashIsObj(x) && typeof x.id === 'string' && x.id) ids.push(x.id);
        cursor = typeof answer.data.nextCursor === 'string' ? answer.data.nextCursor : '';
        if (!cursor) break;
      }
      mark(it, '_relations', k, ids);
      if (cursor) mark(it, '_relationCut', k, ids.length);
    } catch (e) {
      failures += 1;
      mark(it, '_relationFailed', k, String((e && e.message) || e));
    }
  };
  await Promise.all(Array.from({ length: 6 }, async () => { while (i < jobs.length) await one(jobs[i++]); }));
  return items;
}
/** What the preview adds to the entries before they are shaped, in the
    module's order: each relation's links, then the terms. */
async function emdashEnrich(items, arg, ask) {
  const a = emdashIsObj(arg) ? arg : {};
  if (emdashIsObj(a.relations)) await emdashRelations(items, a.relations, ask);
  if (Array.isArray(a.terms) && a.terms.length) await emdashTerms(items, a.terms, ask);
  return items;
}
/** One page of a list as EmDash answers it: the entries, the cursor to the
    next page, and the total where it says one. A refusal inside the envelope
    is said as EmDash said it. */
const emdashPage = (answer) => {
  if (!emdashIsObj(answer)) throw new Error('the answer is not EmDash’s');
  if (answer.success === false) throw new Error(String((answer.error && (answer.error.message ?? answer.error.code)) ?? 'EmDash refused the request'));
  const d = emdashIsObj(answer.data) ? answer.data : {};
  if (!Array.isArray(d.items)) throw new Error('the answer holds no list of entries');
  return { list: d.items, next: typeof d.nextCursor === 'string' ? d.nextCursor : '', total: typeof d.total === 'number' ? d.total : undefined };
};
/** What the rich text holds that is not drawn, counted by type and said once. */
const emdashNotes = (items) => {
  const seen = new Map();
  const walk = (v, depth) => {
    if (depth > 5) return;
    if (emdashIsPt(v)) { for (const t of ptUndrawn(v)) seen.set(t, (seen.get(t) ?? 0) + 1); return; }
    if (Array.isArray(v)) for (const x of v) walk(x, depth + 1);
    else if (emdashIsObj(v)) for (const x of Object.values(v)) walk(x, depth + 1);
  };
  /* Relations not read, or cut, by field: once each, with the first reason. */
  const failed = new Map();
  const cut = new Map();
  for (const it of Array.isArray(items) ? items : []) {
    walk(it && it.data, 0);
    for (const [k, why] of Object.entries(emdashIsObj(it && it._relationFailed) ? it._relationFailed : {})) {
      const f = failed.get(k) ?? { n: 0, why: String(why) };
      f.n += 1;
      failed.set(k, f);
    }
    for (const k of Object.keys(emdashIsObj(it && it._relationCut) ? it._relationCut : {})) cut.set(k, (cut.get(k) ?? 0) + 1);
  }
  return [...seen].map(([t, n]) => n + (n === 1 ? ' block' : ' blocks') + ' of the type "' + t + '" ' + (n === 1 ? 'is' : 'are')
    + ' left out of the rich text: only EmDash’s own block types are drawn here.')
    .concat([...failed].map(([k, f]) => 'The relation "' + k + '" was not read for ' + f.n + (f.n === 1 ? ' entry, which has' : ' entries, which have')
      + ' it empty (' + f.why + ').'))
    .concat([...cut].map(([k, n]) => 'The relation "' + k + '" links more than 1,000 entries on ' + n + (n === 1 ? ' entry' : ' entries')
      + ': only the first 1,000 are kept.'))
    /* and the embeds held back while the entries were shaped */
    .concat(cmsFramesSaid());
};

const withDates = (rows, keys, locale, style) => {
  let format;
  try { format = new Intl.DateTimeFormat(locale || 'en', { dateStyle: style, timeZone: 'UTC' }); }
  catch { format = new Intl.DateTimeFormat('en', { dateStyle: style, timeZone: 'UTC' }); }
  return rows.map((row) => {
    if (!row || typeof row !== 'object') return row;
    const out = { ...row };
    for (const key of keys) {
      const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(row[key] ?? ''));
      if (m) out[key + '_text'] = format.format(new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])));
    }
    return out;
  });
};

const ENDPOINT = "https://emdash-c46x.xc1.app/_emdash/api/content/posts?status=published&limit=100";
/** What every entry is shaped with: the site, where EmDash puts an entry, and its fields' types, as the last test found them. */
const EMDASH = {"root":"https://emdash-c46x.xc1.app","pattern":"/posts/{slug}","fields":{"title":"string","featured_image":"image","content":"portableText","excerpt":"text"}};
/** The taxonomies each entry's terms are asked in — one request per entry per taxonomy. */
const TERMS = ["category","tag"];
const API = "https://emdash-c46x.xc1.app/_emdash/api";

const HEADERS = {
  "Authorization": "Bearer " + SECRET,
};

/** One request under the API, with the token. */
const emdashAsk = async (path) => {
  const res = await fetch(API + path, { headers: HEADERS, signal: AbortSignal.timeout(TIMEOUT) });
  if (!res.ok) throw new Error("EmDash CMS: " + API + path + ' answered ' + res.status);
  return res.json();
};

async function load() {
  if (!SECRET) throw new Error("EmDash CMS: EMDASH_TOKEN is not set — add it to .env, and to the host's environment for the deploy.");
  const all = [];
  /* EmDash hands out a hundred at a time, and a cursor to the next hundred. */
  let cursor = '';
  for (let page = 1; page <= 50; page++) {
    const res = await fetch(ENDPOINT + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''), { headers: HEADERS, signal: AbortSignal.timeout(TIMEOUT) });
    if (!res.ok) throw new Error("EmDash CMS: " + ENDPOINT + ' answered ' + res.status);
    const { list, next } = emdashPage(await res.json());
    all.push(...list);
    cursor = next;
    if (!cursor) break;
  }
  if (cursor) console.warn("EmDash CMS: more than 5,000 entries — only the first 5,000 were fetched.");
  const entries = all;
  await emdashTerms(entries, TERMS, emdashAsk);
  for (const note of emdashNotes(entries)) console.warn("EmDash CMS: " + note);
  return withDates(emdashRefs(entries.map((row) => emdashRow(row, EMDASH)), EMDASH), ["publishedAt","updatedAt","createdAt"], "en", "long");
}

/** A certificate Node does not trust — a site on this computer signed by a
    local authority (mkcert, which DDEV uses) — said with what fixes it. */
const certHint = (error) => (/^(UNABLE_TO_GET_ISSUER_CERT_LOCALLY|UNABLE_TO_VERIFY_LEAF_SIGNATURE|SELF_SIGNED_CERT_IN_CHAIN|DEPTH_ZERO_SELF_SIGNED_CERT)$/.test(String(error?.cause?.code ?? error?.code ?? ''))
  ? " (set NODE_EXTRA_CA_CERTS to the local authority's file and build again — for DDEV: NODE_EXTRA_CA_CERTS=\"$(mkcert -CAROOT)/rootCA.pem\")" : '');

const SNAPSHOT = resolve(process.cwd(), "node_modules/.cache/sitereal/sources/emdash-posts.json");
/** Set by sitereal for its own build check, and by nothing else. */
const CHECK = !!process.env.SITEREAL_BUILD_CHECK;
/** SITEREAL_ALLOW_SNAPSHOT=1: build with the last rows when the source cannot be reached, rather than stop (sitereal's own check and astro dev always may: neither is a deploy). */
const ALLOW = CHECK || (typeof import.meta.env !== 'undefined' && !!import.meta.env.DEV) || /^(1|true|yes)$/i.test(process.env.SITEREAL_ALLOW_SNAPSHOT ?? '');
/** SITEREAL_STRICT=1: stop rather than build with the last rows, whatever allows them (never in sitereal's own check). */
const STRICT = !CHECK && /^(1|true|yes)$/i.test(process.env.SITEREAL_STRICT ?? '');

/** Keep what a fetch gave, for the build that cannot make one. */
async function kept(rows) {
  const text = JSON.stringify(rows);
  try {
    if (CHECK || text !== await readFile(SNAPSHOT, 'utf8').catch(() => '')) {
      await mkdir(dirname(SNAPSHOT), { recursive: true });
      await writeFile(SNAPSHOT, text);
    }
  } catch { /* a read-only disk is not a reason to fail a build that has its rows */ }
  return rows;
}

/** The rows of the last fetch that worked, when this one did not. */
async function lastRows(error) {
  const rows = await readFile(SNAPSHOT, 'utf8').then(JSON.parse).catch(() => null);
  if (!Array.isArray(rows)) throw error;
  /* an answer that was not rows names the source already */
  const why = whyFailed(error);
  const said = why.startsWith("EmDash CMS: ") ? why : "EmDash CMS: " + why;
  if (STRICT) throw new Error(said + certHint(error) + ' — SITEREAL_STRICT is set, so the build stops rather than use the ' + rows.length + ' rows of the last fetch that worked.');
  if (!ALLOW) throw new Error(said + certHint(error) + ' — the build stops rather than use the ' + rows.length + ' rows of the last fetch that worked. Set SITEREAL_ALLOW_SNAPSHOT=1 to build with them anyway.');
  console.warn(said + ' — building with the ' + rows.length + ' rows of the last fetch that worked.' + certHint(error));
  return rows;
}

/** While sitereal checks that the site still builds — after every save —
    the rows of a fetch made in the last quarter of an hour are the answer:
    the question is whether the site builds, not what was published since,
    and asking the source on every save is asking it hundreds of times a day. */
async function checked() {
  /* And only rows this module made: one rewritten since — another folder
     for the entry pages, another path into the answer — shapes them
     differently, and the check would be of a site that no longer exists. */
  const since = await stat(resolve(process.cwd(), "src/data/sources/emdash-posts.js")).then((f) => f.mtimeMs, () => 0);
  const fresh = await stat(SNAPSHOT).then((f) => Date.now() - f.mtimeMs < 15 * 60_000 && f.mtimeMs >= since, () => false);
  const rows = fresh ? await readFile(SNAPSHOT, 'utf8').then(JSON.parse).catch(() => null) : null;
  return Array.isArray(rows) ? rows : load().then(kept, lastRows);
}

/** Why it failed, in words. Node's fetch says "fetch failed" and puts the reason
    in its cause; an address that answers on ::1 and 127.0.0.1 (localhost) and
    refuses both makes that cause an AggregateError with no message, only a code
    and the two refusals. */
const whyFailed = (error) => {
  const c = error?.cause;
  return String(c?.message || [...new Set((Array.isArray(c?.errors) ? c.errors : []).map((e) => e?.message).filter(Boolean))].join(', ') || c?.code || error?.message || error);
};
/** A failure that says which source it was: node's own is "fetch failed". */
const named = (error) => {
  const why = error?.name === 'TimeoutError' ? 'no answer within ' + TIMEOUT / 1000 + ' seconds' : whyFailed(error) + certHint(error);
  throw new Error(why.startsWith("EmDash CMS: ") ? why : "EmDash CMS: " + why);
};

/* One fetch per build, shared by every page. Under astro dev (the preview) the
   module stays loaded: there a page asked again asks again, so what was
   published since shows — the loops of one page, within two seconds, share. */
const DEV = typeof import.meta.env !== 'undefined' && !!import.meta.env.DEV;
let rows;
let asked = 0;
/** Every row of "EmDash CMS". */
export function emdashPosts() {
  if (DEV && rows && Date.now() - asked > 2000) rows = undefined;
  if (!rows) asked = Date.now();
  return (rows ??= (CHECK ? checked() : load().then(kept, lastRows)).catch(named));
}
